import React, { useEffect, useMemo, useState } from 'react';
import { Alert, Button, Form, Spinner } from 'react-bootstrap';
import { bilingual, getTimeZoneDetails, readStoredCity } from '../panchangam/helpers';
import BirthLocationPicker from '../horoscope/BirthLocationPicker';
import SouthIndianChart from '../horoscope/SouthIndianChart';
import { resolveBirthInstant } from '../horoscope/horoscopeCalculator';
import { calculateMarriageMatch } from './marriageCalculator';
import { downloadMarriageReport } from './marriageReport';
import '../horoscope/Horoscope.css';
import './MarriageMatch.css';

const phrase = (language, te, en) => bilingual({ te, en }, language);
const value = (language, item) => bilingual(item, language);
const emptyPerson = () => ({ name: '', birthDate: '', birthTime: '', city: readStoredCity(), selectedOffset: '', timeAccuracy: 'exact' });
const readLanguage = () => { try { const item = sessionStorage.getItem('marriage-language') || sessionStorage.getItem('horoscope-language'); return ['te', 'en', 'both'].includes(item) ? item : 'both'; } catch { return 'both'; } };

function PersonForm({ role, person, setPerson, language, openLocation }) {
  const resolved = useMemo(() => {
    if (!person.birthDate || !person.birthTime || !person.city?.tz) return null;
    try { return resolveBirthInstant({ birthDate: person.birthDate, birthTime: person.birthTime, timezone: person.city.tz, selectedOffset: person.selectedOffset }); } catch { return null; }
  }, [person]);
  const timezone = getTimeZoneDetails(person.city.tz, resolved?.instant || new Date());
  const update = (key) => (event) => setPerson((current) => ({ ...current, [key]: event.target.value, ...(['birthDate', 'birthTime'].includes(key) ? { selectedOffset: '' } : {}) }));
  const isBride = role === 'bride';

  return (
    <section className={`marriage-person-card ${isBride ? 'is-bride' : ''}`}>
      <div className="marriage-person-heading"><span>{isBride ? '02' : '01'}</span><div><small>{phrase(language, isBride ? 'వధువు వివరాలు' : 'వరుడు వివరాలు', isBride ? 'BRIDE DETAILS' : 'GROOM DETAILS')}</small><h2>{phrase(language, isBride ? 'వధువు జాతకం' : 'వరుడు జాతకం', isBride ? 'Bride horoscope' : 'Groom horoscope')}</h2></div></div>
      <Form.Group><Form.Label>{phrase(language, 'పూర్తి పేరు', 'Full name')}</Form.Label><Form.Control required value={person.name} onChange={update('name')} placeholder={phrase(language, 'నివేదికలో కనిపించే పేరు', 'Name shown in the report')} /></Form.Group>
      <div className="marriage-form-grid">
        <Form.Group><Form.Label>{phrase(language, 'జనన తేదీ', 'Date of birth')}</Form.Label><Form.Control required type="date" value={person.birthDate} onChange={update('birthDate')} /></Form.Group>
        <Form.Group><Form.Label>{phrase(language, 'జనన సమయం', 'Time of birth')}</Form.Label><Form.Control required type="time" step="60" value={person.birthTime} onChange={update('birthTime')} /></Form.Group>
      </div>
      <Form.Group><Form.Label>{phrase(language, 'జన్మస్థలం', 'Birth place')}</Form.Label><button type="button" className="marriage-place" onClick={openLocation}><span>⌖</span><span><strong>{person.city.name}</strong><small>{person.city.tz} · {Number(person.city.lat).toFixed(4)}, {Number(person.city.lng).toFixed(4)}</small></span><b>{phrase(language, 'మార్చండి', 'Change')}</b></button></Form.Group>
      {resolved?.possibleOffsets?.length > 1 && <fieldset className="marriage-offset"><legend>{phrase(language, 'ఈ సమయం రెండుసార్లు వచ్చింది — సరైన UTC భేదం ఎంచుకోండి', 'This time occurred twice — select the recorded UTC offset')}</legend>{resolved.possibleOffsets.map((option) => <label key={option.offset}><input required type="radio" name={`${role}-offset`} checked={String(person.selectedOffset) === String(option.offset)} value={option.offset} onChange={update('selectedOffset')} /><span>{option.label}</span></label>)}</fieldset>}
      <div className="marriage-confidence"><label><input type="radio" name={`${role}-accuracy`} checked={person.timeAccuracy === 'exact'} onChange={() => setPerson((current) => ({ ...current, timeAccuracy: 'exact' }))} /> {phrase(language, 'ఖచ్చిత సమయం', 'Exact time')}</label><label><input type="radio" name={`${role}-accuracy`} checked={person.timeAccuracy === 'approximate'} onChange={() => setPerson((current) => ({ ...current, timeAccuracy: 'approximate' }))} /> {phrase(language, 'సుమారు సమయం', 'Approximate time')}</label></div>
      <div className="marriage-time-proof"><span>◷</span><div><strong>{timezone.label}</strong><small>{phrase(language, 'జనన తేదీకి చారిత్రక DST స్వయంగా వర్తిస్తుంది.', 'Historical DST is applied for this birth date.')}</small></div></div>
    </section>
  );
}

const BirthSummary = ({ report, role, language }) => <article className="marriage-birth-summary"><small>{phrase(language, role === 'groom' ? 'వరుడు' : 'వధువు', role === 'groom' ? 'GROOM' : 'BRIDE')}</small><h3>{report.person.name}</h3><div><span>{phrase(language, 'లగ్నం', 'Lagna')}<b>{value(language, report.ascendant.rashi.name)}</b></span><span>{phrase(language, 'రాశి', 'Rashi')}<b>{value(language, report.moon.rashi.name)}</b></span><span>{phrase(language, 'నక్షత్రం', 'Nakshatra')}<b>{value(language, report.moon.nakshatra.name)} · {report.moon.nakshatra.pada}</b></span><span>{phrase(language, 'స్థానిక సమయం', 'Local time')}<b>{report.timezone.name} · UTC{report.timezone.offset}</b></span></div></article>;

function Results({ report, language, download, downloading }) {
  const [section, setSection] = useState('overview');
  const nav = [
    ['overview', 'సారాంశం', 'Overview'], ['porutham', '10 పొరుత్తాలు', '10 Poruthams'], ['guna', '36 గుణాలు', '36 Gunas'],
    ['charts', 'చక్రాలు', 'Charts'], ['kuja', 'కుజ + దశ', 'Kuja + Dasha'], ['reading', 'వివరణ', 'Reading'], ['method', 'పద్ధతి', 'Method'],
  ];
  const failed = report.poruthams.filter((item) => !item.passed);
  const grade = { strong: ['బలమైన ప్రాథమిక సరిపోలిక', 'Strong initial match'], workable: ['పని చేయగల సరిపోలిక', 'Workable with discussion'], review: ['నిపుణుల సమీక్ష అవసరం', 'Expert review advised'] }[report.grade];
  const closest = report.dashaSandhi.closest;

  return <section className="marriage-results">
    <section className="marriage-result-hero"><div><span className="horoscope-kicker">{phrase(language, 'సమగ్ర వివాహ సరిపోలిక', 'LAYERED MARRIAGE MATCH')}</span><h2>{report.groom.person.name} <i>+</i> {report.bride.person.name}</h2><p>{phrase(language, 'ఒక స్కోరు కాదు — ప్రతి గణన, నియమం, జాగ్రత్తను విడిగా చూడండి.', 'Not one score — inspect every calculation, rule and caution separately.')}</p></div><div className="marriage-result-score"><strong>{report.southScore}<small>/10</small></strong><span>{phrase(language, 'దక్షిణ భారత పొరుత్తాలు', 'South Indian Poruthams')}</span></div><div className="marriage-result-score"><strong>{report.ashtakoota.total}<small>/36</small></strong><span>{phrase(language, 'అష్టకూట గుణాలు', 'Ashtakoota Gunas')}</span></div></section>
    <div className={`marriage-verdict is-${report.grade}`}><span>{report.grade === 'strong' ? '✓' : '!'}</span><div><small>{phrase(language, 'సమగ్ర పఠనం', 'BALANCED READING')}</small><strong>{phrase(language, grade[0], grade[1])}</strong><p>{report.gates.length ? phrase(language, `ప్రధాన ద్వార పరీక్షలు: ${report.gates.join(', ')}. మొత్తం స్కోరు వీటిని రద్దు చేయదు.`, `Critical gates flagged: ${report.gates.join(', ')}. The total does not override them.`) : phrase(language, 'రజ్జు, వేధ ప్రధాన ద్వారాలు అనుకూలంగా ఉన్నాయి; మిగతా జాతక స్థాయిలను కూడా చదవండి.', 'Rajju and Vedha gates are clear; still review the remaining chart layers.')}</p></div></div>
    <nav className="marriage-nav" aria-label="Marriage report sections">{nav.map(([key, te, en]) => <button key={key} type="button" className={section === key ? 'active' : ''} onClick={() => setSection(key)}>{phrase(language, te, en)}</button>)}</nav>
    {section === 'kuja' && <div className="marriage-plain-overview"><b>{phrase(language, 'ఈ జంటకు సులభంగా అర్థం', 'What this means for this couple')}</b><p>{value(language, report.diagnosticsSummary)}</p></div>}

    {section === 'overview' && <div className="marriage-section"><div className="marriage-paired"><BirthSummary report={report.groom} role="groom" language={language} /><BirthSummary report={report.bride} role="bride" language={language} /></div><div className="marriage-dashboard"><article><small>{phrase(language, 'అనుకూల పొరుత్తాలు', 'PORUTHAMS PASSED')}</small><strong>{report.southScore}/10</strong><span>{failed.length ? `${failed.length} ${phrase(language, 'సమీక్ష', 'to review')}` : phrase(language, 'అన్నీ అనుకూలం', 'all clear')}</span></article><article><small>{phrase(language, 'గుణ మొత్తం', 'GUNA TOTAL')}</small><strong>{report.ashtakoota.total}/36</strong><span>{report.ashtakoota.total >= 25 ? phrase(language, 'మంచి చంద్ర-నక్షత్ర మద్దతు', 'good lunar support') : phrase(language, 'స్కోరుకు మించి చూడండి', 'review beyond the score')}</span></article><article><small>{phrase(language, 'కుజ / పాప సామ్యం', 'KUJA / PAPA BALANCE')}</small><strong>Δ {report.kuja.balance} / {report.papaSamyam.balance}</strong><span>{phrase(language, 'కుజ మరియు పాప భార తేడాలు', 'Kuja and malefic-load differences')}</span></article><article><small>{phrase(language, 'దశా సంధి', 'DASHA SANDHI')}</small><strong>{closest ? Math.round(closest.days) : '—'}<small>{closest ? phrase(language, ' రోజులు', ' days') : ''}</small></strong><span>{report.dashaSandhi.status}</span></article></div><div className="marriage-explain"><h3>{phrase(language, 'ఫలితాన్ని ఎలా చదవాలి', 'How to read this result')}</h3><p>{value(language, report.method.note)}</p><p>{phrase(language, 'ముందుగా రజ్జు, వేధ చూడండి. తర్వాత 10 పొరుత్తాలు, 36 గుణాలు, కుజ/పాప సామ్యం, దశా సంధి, D1/D9 జాతక ఆధారాలను కలిపి చదవండి. ఏ ఒక్క సంఖ్య వివాహాన్ని హామీ ఇవ్వదు లేదా తిరస్కరించదు.', 'Start with Rajju and Vedha. Then layer the 10 Poruthams, 36 Gunas, Kuja/Papa balance, Dasha Sandhi and D1/D9 chart evidence. No single number guarantees or rejects a marriage.')}</p></div></div>}

    {section === 'porutham' && <div className="marriage-section"><div className="marriage-section-title"><div><small>{phrase(language, 'దక్షిణ భారత పద్ధతి', 'SOUTH INDIAN METHOD')}</small><h2>{phrase(language, '10 పొరుత్తాలు — పూర్తి ఆధారంతో', '10 Poruthams — with full evidence')}</h2></div><strong>{report.southScore}/10</strong></div><div className="marriage-factor-list">{report.poruthams.map((item, index) => <article key={item.key} className={`${item.passed ? 'pass' : 'review'} ${item.importance === 'critical' ? 'critical' : ''}`}><div className="marriage-factor-index">{String(index + 1).padStart(2, '0')}</div><div><small>{item.importance === 'critical' ? phrase(language, 'ప్రధాన ద్వార పరీక్ష', 'CRITICAL GATE') : phrase(language, 'సంప్రదాయ పరీక్ష', 'TRADITIONAL CHECK')}</small><h3>{value(language, item.name)}</h3><strong>{value(language, item.evidence)}</strong><p>{value(language, item.reading)}</p><b className="marriage-plain-label">{phrase(language, 'ఈ జంటకు సులభంగా అర్థం', 'What this means for this couple')}</b><p className="marriage-plain-summary">{value(language, item.summary)}</p><details><summary>{phrase(language, 'గణన నియమం చూపించండి', 'Show calculation rule')}</summary><p>{value(language, item.rule)}</p></details></div><b>{item.passed ? phrase(language, 'అనుకూలం', 'MATCH') : phrase(language, 'సమీక్ష', 'REVIEW')}</b></article>)}</div></div>}

    {section === 'guna' && <div className="marriage-section"><div className="marriage-section-title"><div><small>{phrase(language, 'అష్టకూట పద్ధతి', 'ASHTAKOOTA SYSTEM')}</small><h2>{phrase(language, '36 గుణాలు — 8 కూటాలు', '36 Gunas — 8 Kootas')}</h2></div><strong>{report.ashtakoota.total}/36</strong></div><div className="marriage-guna-table"><div className="head"><span>{phrase(language, 'కూటం', 'Group')}</span><span>{report.groom.person.name}</span><span>{report.bride.person.name}</span><span>{phrase(language, 'గుణాలు', 'Points')}</span><span>{phrase(language, 'గరిష్ఠం', 'Max')}</span></div>{report.ashtakoota.factors.map((item) => <article key={item.key}><span><strong>{value(language, item.name)}</strong><small>{value(language, item.explanation)}</small></span><span data-label={report.groom.person.name}>{value(language, item.groomValue)}</span><span data-label={report.bride.person.name}>{value(language, item.brideValue)}</span><b>{item.score}</b><b>{item.max}</b><small className="marriage-guna-basis">{value(language, item.basis)}</small><p className="marriage-guna-summary"><b>{phrase(language, 'సులభమైన అర్థం', 'Plain meaning')}</b>{value(language, item.summary)}</p></article>)}</div><div className={`marriage-guna-verdict is-${report.grade}`}><small>{phrase(language, 'స్కోరు అర్థం', 'WHAT THE SCORE MEANS')}</small><h3>{value(language, report.recommendation.title)}</h3><p>{value(language, report.recommendation.text)}</p></div><Alert variant="warning">{phrase(language, '18 లేదా 25 వంటి పరిమితులు ప్రాంతీయ పని నియమాలు మాత్రమే. ఒకే నాడి, భకూటం లేదా తక్కువ స్కోరుకు కుటుంబ-పద్ధతి మినహాయింపులు ఉండవచ్చు; ఈ యాప్ వాటిని ఊహించదు.', 'Thresholds such as 18 or 25 are regional working rules. Lineage-specific exceptions may exist for Nadi, Bhakoot or a low total; this app does not guess them.')}</Alert></div>}

    {section === 'charts' && <div className="marriage-section"><div className="marriage-section-title"><div><small>D1 + D9</small><h2>{phrase(language, 'రెండు జాతకాల పక్కపక్కన పరిశీలన', 'Both charts, side by side')}</h2></div></div><div className="marriage-chart-pair"><SouthIndianChart report={report.groom} type="d1" language={language} compact /><SouthIndianChart report={report.bride} type="d1" language={language} compact /><SouthIndianChart report={report.groom} type="d9" language={language} compact /><SouthIndianChart report={report.bride} type="d9" language={language} compact /></div><div className="marriage-indicator-grid">{[['groom', report.groom], ['bride', report.bride]].map(([key, person]) => { const item = report.indicators[key]; return <article key={key}><small>{person.person.name}</small><h3>{phrase(language, 'వివాహ జాతక ఆధారాలు', 'Marriage chart evidence')}</h3><dl><div><dt>{phrase(language, '7వ రాశ్యాధిపతి', '7th lord')}</dt><dd>{item.seventhLord} · H{item.seventhLordHouse}</dd></div><div><dt>{phrase(language, '7వ భావ గ్రహాలు', '7th-house planets')}</dt><dd>{item.seventhHousePlanets.join(', ') || phrase(language, 'లేవు', 'None')}</dd></div><div><dt>{phrase(language, 'శుక్రుడు', 'Venus')}</dt><dd>H{item.venusHouse} · {item.venusDignity}</dd></div><div><dt>{phrase(language, 'గురువు', 'Jupiter')}</dt><dd>H{item.jupiterHouse} · {item.jupiterDignity}</dd></div></dl></article>; })}</div><p className="marriage-footnote">{phrase(language, 'ఇవి లేబుల్ చేసిన స్థానాలు మాత్రమే; దృష్టులు, యుతులు, బలం, దశలు మరియు ప్రాంతీయ కారక నియమాలతో మానవ జ్యోతిష్కుడు మరింత లోతుగా చదవాలి.', 'These are labelled placements, not a deterministic verdict. A human astrologer may deepen the reading with aspects, conjunctions, strength, Dashas and regional Karaka rules.')}</p></div>}

    {section === 'kuja' && <div className="marriage-section"><div className="marriage-section-title"><div><small>{phrase(language, 'స్కోరు బయట ఉన్న పరీక్షలు', 'BEYOND THE SCORES')}</small><h2>{phrase(language, 'కుజ, పాప సామ్యం మరియు దశా సంధి', 'Kuja, Papa Samyam and Dasha Sandhi')}</h2></div></div><div className="marriage-kuja-pair">{[['groom', report.groom], ['bride', report.bride]].map(([key, person]) => { const item = report.kuja[key]; return <article key={key}><small>{person.person.name}</small><strong>{item.intensity}<i>/3</i></strong><span>{phrase(language, 'కుజ సూచనలు', 'Kuja references flagged')}</span><div><b>{phrase(language, 'లగ్నం నుండి', 'From Lagna')}<em>H{item.houses.lagna}</em></b><b>{phrase(language, 'చంద్రుని నుండి', 'From Moon')}<em>H{item.houses.moon}</em></b><b>{phrase(language, 'శుక్రుని నుండి', 'From Venus')}<em>H{item.houses.venus}</em></b></div></article>; })}</div><div className="marriage-explain"><h3>{phrase(language, 'ఉపయోగించిన కుజ నియమం', 'Kuja convention used')}</h3><p>{report.kuja.groom.convention}. {phrase(language, 'తెలుగు/దక్షిణ భారత పద్ధతుల్లో 2వ భావాన్ని చేర్చడం మారవచ్చు. మేము దాన్ని చేర్చామని స్పష్టంగా చూపిస్తున్నాం; ఆటోమేటిక్ రద్దులను ఊహించము.', 'Second-house inclusion varies across Telugu/South Indian lineages. We show that it is included here and do not assume automatic cancellations.')}</p></div><div className="marriage-papa"><div><small>{phrase(language, 'పాప సామ్యం', 'PAPA SAMYAM')}</small><h3>{phrase(language, 'సహజ పాపగ్రహ భార సమతుల్యం', 'Natural-malefic load balance')}</h3><p>{phrase(language, 'లగ్నం, చంద్రుడు, శుక్రుడు నుండి కుజ, శని, రాహు, సూర్య స్థానాలను ఒకే పారదర్శక బరువులతో పోలుస్తుంది.', 'Compares Mars, Saturn, Rahu and Sun from Lagna, Moon and Venus with one transparent weighting table.')}</p></div><div className="marriage-papa-scores"><span><small>{report.groom.person.name}</small><strong>{report.papaSamyam.groom.score}</strong></span><i>Δ {report.papaSamyam.balance}</i><span><small>{report.bride.person.name}</small><strong>{report.papaSamyam.bride.score}</strong></span></div><details><summary>{phrase(language, '12 స్థానాల ఆధారం చూపించండి', 'Show all 12 placement checks')}</summary><div className="marriage-papa-table">{[['groom', report.groom], ['bride', report.bride]].map(([key, person]) => <article key={key}><strong>{person.person.name}</strong>{report.papaSamyam[key].placements.map((placement) => <span key={`${placement.reference}-${placement.planet}`}>{placement.reference} · {placement.planet}<b>H{placement.house}</b><em>{placement.points}</em></span>)}</article>)}</div></details><p className="marriage-footnote">{report.papaSamyam.groom.convention}. {phrase(language, 'ఇది పోలిక స్క్రీన్ మాత్రమే; దృష్టులు, బలం లేదా ప్రాంతీయ రద్దు నియమాలను ఊహించదు.', 'This is a balance screen only; it does not guess aspects, strength or regional cancellation rules.')}</p></div><div className={`marriage-dasha ${report.dashaSandhi.status}`}><span>◷</span><div><small>DASHA SANDHI</small><h3>{closest ? phrase(language, `సమీప మార్పులు ${Math.round(closest.days)} రోజుల దూరంలో`, `Closest changes are ${Math.round(closest.days)} days apart`) : phrase(language, 'సమీప సంధి లేదు', 'No close boundary')}</h3><p>{value(language, report.dashaSandhi.rule)}</p>{closest && <p>{report.groom.person.name}: {closest.first.lord.name.en} · {new Date(closest.first.date).toLocaleDateString()}<br />{report.bride.person.name}: {closest.second.lord.name.en} · {new Date(closest.second.date).toLocaleDateString()}</p>}</div></div></div>}

    {section === 'reading' && <div className="marriage-section"><div className="marriage-section-title"><div><small>{phrase(language, 'స్పష్టమైన సంబంధ పఠనం', 'CLEAR RELATIONSHIP READING')}</small><h2>{phrase(language, 'వివాహ జీవితం — ఆధారం మరియు సాధారణ వివరణ', 'Married-life outlook — evidence and plain explanation')}</h2></div></div><div className="marriage-outlook-grid">{report.outlook.map((item, index) => <article className={item.tone} key={item.key}><header><span>{String(index + 1).padStart(2, '0')}</span><h3>{value(language, item.title)}</h3></header><b>{phrase(language, 'గణన ఆధారం', 'Calculation evidence')}</b><p>{value(language, item.evidence)}</p><b>{phrase(language, 'సాధారణ భాషలో అర్థం', 'Plain-language meaning')}</b><p>{value(language, item.reading)}</p></article>)}</div><div className="marriage-reading-grid"><article className="positive"><span>✓</span><h3>{phrase(language, 'సంప్రదాయ బలాలు', 'Traditional strengths')}</h3><ul>{report.poruthams.filter((item) => item.passed).map((item) => <li key={item.key}><strong>{value(language, item.name)}</strong><span>{value(language, item.reading)}</span></li>)}</ul></article><article className="caution"><span>!</span><h3>{phrase(language, 'సమీక్షించాల్సినవి', 'Points to review')}</h3>{failed.length ? <ul>{failed.map((item) => <li key={item.key}><strong>{value(language, item.name)}</strong><span>{value(language, item.evidence)} {value(language, item.reading)}</span></li>)}</ul> : <p>{phrase(language, '10 పొరుత్తాల్లో సమీక్ష సూచన లేదు. అయినా కుజ, దశా, D1/D9 మరియు వాస్తవ సంబంధ అంశాలు చూడాలి.', 'No Porutham is flagged, but Kuja, Dasha, D1/D9 and real-world relationship factors still matter.')}</p>}</article></div><div className="marriage-conversation"><h3>{phrase(language, 'జంట మాట్లాడుకోవాల్సిన 6 విషయాలు', 'Six conversations worth having')}</h3><ol><li>{phrase(language, 'సంఘర్షణలో ఎలా మాట్లాడతాం?', 'How do we communicate during conflict?')}</li><li>{phrase(language, 'డబ్బు, పొదుపు, అప్పులపై అంచనాలు ఏమిటి?', 'What are our expectations around money, saving and debt?')}</li><li>{phrase(language, 'కుటుంబ సరిహద్దులు, సంరక్షణ బాధ్యతలు ఎలా?', 'How will we handle family boundaries and care duties?')}</li><li>{phrase(language, 'పిల్లలు, వృత్తి, నివాసంపై లక్ష్యాలు సరిపోతున్నాయా?', 'Do our goals for children, career and location align?')}</li><li>{phrase(language, 'ఆరోగ్యం, విశ్వాసం, వ్యక్తిగత స్వేచ్ఛపై అవసరాలు?', 'What do we need around health, faith and personal space?')}</li><li>{phrase(language, 'సమ్మతి, గౌరవం, భద్రత ఎల్లప్పుడూ ఉన్నాయా?', 'Are consent, respect and safety consistently present?')}</li></ol></div></div>}

    {section === 'method' && <div className="marriage-section"><div className="marriage-section-title"><div><small>{phrase(language, 'పరిశీలించగల గణన', 'INSPECTABLE CALCULATION')}</small><h2>{phrase(language, 'పద్ధతి మరియు మూలాల పారదర్శకత', 'Method and source transparency')}</h2></div><Button onClick={download} disabled={downloading}>{downloading ? <Spinner size="sm" /> : '⇩'} {phrase(language, 'పూర్తి PDF', 'Full PDF')}</Button></div><div className="marriage-method-grid">{Object.entries(report.method.astronomy).map(([key, item]) => <article key={key}><small>{key}</small><strong>{item}</strong></article>)}</div><div className="marriage-explain"><h3>{phrase(language, 'గణన పొరలు', 'Calculation layers')}</h3><p>{phrase(language, 'ప్రతి వ్యక్తి గ్రహ దీర్ఘాంశాలు Astronomy Engineతో గణించి Lahiri/Chitrapaksha నిరయణ రాశికి మార్చబడతాయి. జన్మస్థలం, చారిత్రక IANA సమయ మండలి, DST ఆధారంగా లగ్నం వేర్వేరుగా గణించబడుతుంది. 10 పొరుత్తాలు చంద్ర నక్షత్రం/రాశిపై; 36 గుణాలు వేరే అష్టకూట పట్టికపై; కుజం, దశా సంధి, D1/D9 విడిగా ఉంటాయి.', 'Each person’s planetary longitudes use Astronomy Engine and are converted to the documented Lahiri/Chitrapaksha sidereal zodiac. Lagna is independently calculated from birthplace, historical IANA timezone and DST. The 10 Poruthams use Moon star/sign; the 36 Gunas use a separate Ashtakoota table; Kuja, Dasha Sandhi and D1/D9 remain separate layers.')}</p><div className="marriage-source-links"><a href="https://api.prokerala.com/reports/sample/porutham-tamil-en.pdf" target="_blank" rel="noreferrer">South Indian Porutham sample ↗</a><a href="https://www.drikpanchang.com/tutorials/jyotisha/kundali-match/ashta-kuta/vashya-kuta.html?lang=en" target="_blank" rel="noreferrer">Vashya categories ↗</a><a href="https://github.com/cosinekitty/astronomy" target="_blank" rel="noreferrer">Astronomy Engine ↗</a><a href="https://www.iana.org/time-zones" target="_blank" rel="noreferrer">IANA timezones ↗</a></div></div><Alert variant="warning">{phrase(language, 'ఇది సంప్రదాయ జ్యోతిష విద్యా సాధనం. రజ్జు, వేధ, నాడి, కుజ లేదా దశా సూచన ఉన్నప్పుడు కుటుంబ పద్ధతి తెలిసిన అర్హుడైన జ్యోతిష్కుడితో సమీక్షించండి. వివాహానికి ఇద్దరి స్వేచ్ఛా సమ్మతి తప్పనిసరి.', 'This is a traditional astrology education tool. When Rajju, Vedha, Nadi, Kuja or Dasha is flagged, review it with a qualified astrologer familiar with your lineage. Free consent from both people is essential.')}</Alert></div>}
  </section>;
}

function MarriageMatch() {
  const [language, setLanguage] = useState(readLanguage);
  const [groom, setGroom] = useState(emptyPerson);
  const [bride, setBride] = useState(emptyPerson);
  const [locationFor, setLocationFor] = useState('');
  const [report, setReport] = useState(null);
  const [error, setError] = useState('');
  const [calculating, setCalculating] = useState(false);
  const [downloading, setDownloading] = useState(false);
  useEffect(() => { try { sessionStorage.setItem('marriage-language', language); } catch { /* no-op */ } }, [language]);
  const submit = (event) => { event.preventDefault(); setError(''); setCalculating(true); window.setTimeout(() => { try { const ambiguous = [[groom, 'Groom'], [bride, 'Bride']].find(([person]) => { try { const resolved = resolveBirthInstant({ birthDate: person.birthDate, birthTime: person.birthTime, timezone: person.city.tz, selectedOffset: person.selectedOffset }); return resolved.possibleOffsets.length > 1 && person.selectedOffset === ''; } catch { return false; } }); if (ambiguous) throw new Error(`${ambiguous[1]} birth time occurs twice because clocks changed. Select the correct UTC offset.`); setReport(calculateMarriageMatch({ groom, bride })); window.scrollTo({ top: 0, behavior: 'smooth' }); } catch (issue) { setError(issue.message || 'The match could not be calculated.'); } finally { setCalculating(false); } }, 40); };
  const download = async () => { setDownloading(true); setError(''); try { await downloadMarriageReport(report, language); } catch (issue) { setError(issue.message || 'The PDF could not be created.'); } finally { setDownloading(false); } };
  const chooseLocation = (city) => { if (locationFor === 'groom') setGroom((current) => ({ ...current, city, selectedOffset: '' })); if (locationFor === 'bride') setBride((current) => ({ ...current, city, selectedOffset: '' })); setLocationFor(''); };

  return <main className="horoscope-page marriage-page">
    <header className="horoscope-command-bar marriage-command"><div><button type="button" className="horoscope-back" onClick={() => { window.location.hash = '/panchangam'; }}>← {phrase(language, 'పంచాంగానికి', 'Back to Panchangam')}</button><span className="horoscope-kicker">{phrase(language, 'దక్షిణ భారత వివాహ జ్యోతిషం', 'SOUTH INDIAN MARRIAGE ASTROLOGY')}</span><h1>{phrase(language, 'వివాహ జాతక సరిపోలిక', 'Marriage Horoscope Match')}</h1><p>{phrase(language, '10 పొరుత్తాలు, 36 గుణాలు, D1/D9 చక్రాలు, కుజ/పాప సామ్యం మరియు దశా సంధి', '10 Poruthams, 36 Gunas, D1/D9 charts, Kuja/Papa balance and Dasha Sandhi')}</p></div><div className="horoscope-header-actions"><Form.Select value={language} onChange={(event) => setLanguage(event.target.value)}><option value="both">తెలుగు + English</option><option value="te">తెలుగు</option><option value="en">English</option></Form.Select>{report && <Button variant="outline-secondary" onClick={() => setReport(null)}>{phrase(language, 'కొత్త సరిపోలిక', 'New match')}</Button>}{report && <Button className="horoscope-download" onClick={download} disabled={downloading}>{downloading ? <Spinner size="sm" /> : '⇩'} {phrase(language, 'పూర్తి PDF', 'Full PDF')}</Button>}</div></header>
    {error && <Alert variant="warning" className="horoscope-alert" dismissible onClose={() => setError('')}>{error}</Alert>}
    {!report ? <Form className="marriage-intake" onSubmit={submit}><div className="marriage-intake-intro"><span className="horoscope-kicker">{phrase(language, 'గోప్యం · ఈ పరికరంలోనే గణన', 'PRIVATE · CALCULATED ON THIS DEVICE')}</span><h2>{phrase(language, 'రెండు పూర్తి జనన వివరాలు ఇవ్వండి.', 'Enter both complete birth records.')}</h2><p>{phrase(language, 'జనన సమయాలు, స్థలాలు ఖచ్చితంగా ఉంటే లగ్నం, నవాంశం, భావాల పరిశీలన నమ్మదగినదిగా ఉంటుంది. ప్రతి వ్యక్తికి ఆ తేదీన అమలులో ఉన్న స్థానిక సమయం మరియు DST వాడతాం.', 'Accurate birth times and places make Lagna, Navamsa and house review more reliable. Each person uses the official local time and DST in force on that birth date.')}</p></div><div className="marriage-person-grid"><PersonForm role="groom" person={groom} setPerson={setGroom} language={language} openLocation={() => setLocationFor('groom')} /><PersonForm role="bride" person={bride} setPerson={setBride} language={language} openLocation={() => setLocationFor('bride')} /></div>{(groom.timeAccuracy === 'approximate' || bride.timeAccuracy === 'approximate') && <Alert variant="warning">{phrase(language, 'సుమారు జనన సమయం వల్ల లగ్నం, భావాలు, D9 మారవచ్చు. నక్షత్ర ఆధారిత పొరుత్తాలు స్థిరంగా ఉండవచ్చు కానీ పూర్తి జాతక పఠనం సమీక్ష అవసరం.', 'An approximate birth time can change Lagna, houses and D9. Star-based Poruthams may remain stable, but the full chart reading needs review.')}</Alert>}<div className="marriage-calculate-wrap"><div><strong>{phrase(language, 'మీకు లభించేవి', 'You will receive')}</strong><span>{phrase(language, 'వెబ్‌సైట్ మరియు PDFలో ఒకే పూర్తి వివరాలు · ప్రతి ఫలితానికి నియమం · రెండు భాషలు', 'Same complete detail on website and PDF · rule for every result · both languages')}</span></div><Button type="submit" disabled={calculating}>{calculating ? <><Spinner size="sm" /> {phrase(language, 'రెండు జాతకాలు గణిస్తున్నాం…', 'Calculating both charts…')}</> : <>{phrase(language, 'వివాహ సరిపోలిక గణించండి', 'Calculate Marriage Match')} <span>→</span></>}</Button></div></Form> : <Results report={report} language={language} download={download} downloading={downloading} />}
    <BirthLocationPicker show={Boolean(locationFor)} onHide={() => setLocationFor('')} onSelect={chooseLocation} />
  </main>;
}

export default MarriageMatch;
